<div class="panel"><h2>Dynamische Formularfelder</h2><?php foreach($fields as $f):?><form method="post" action="<?= e(url('admin/special-reports/dynamic-field')) ?>" class="compact-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$f['id'] ?>"><label>Einsatzart<select name="definition_id"><?php foreach($types as $t):?><option value="<?= (int)$t['id'] ?>" <?= (int)$f['definition_id']===(int)$t['id']?'selected':'' ?>><?= e($t['name']) ?></option><?php endforeach;?></select></label><label>Schlüssel<input name="field_key" value="<?= e($f['field_key']) ?>" required></label><label>Bezeichnung<input name="label" value="<?= e($f['label']) ?>" required></label><label>Abschnitt<input name="section_name" value="<?= e($f['section_name']??'Zusatzangaben') ?>" placeholder="z. B. Alarmdaten" required></label><label>Typ<select name="field_type"><?php foreach(['text','textarea','number','date','time','datetime','select','multiselect','checkbox','yesno'] as $t):?><option value="<?= e($t) ?>" <?= $f['field_type']===$t?'selected':'' ?>><?= e($t) ?></option><?php endforeach;?></select></label><label>Optionen<textarea name="options"><?= e(implode("\n",json_decode((string)$f['options_json'],true)?:[])) ?></textarea></label><label class="check-row"><input type="checkbox" name="required" value="1" <?= $f['required']?'checked':'' ?>><span>Pflicht</span></label><label class="check-row"><input type="checkbox" name="active" value="1" <?= $f['active']?'checked':'' ?>><span>Aktiv</span></label><input type="hidden" name="sort_order" value="<?= (int)$f['sort_order'] ?>"><button class="button secondary" type="submit">Speichern</button></form><?php endforeach;?><form method="post" action="<?= e(url('admin/special-reports/dynamic-field')) ?>" class="compact-form"><?= csrf_field() ?><label>Einsatzart<select name="definition_id"><?php foreach($types as $t):?><option value="<?= (int)$t['id'] ?>"><?= e($t['name']) ?></option><?php endforeach;?></select></label><label>Schlüssel<input name="field_key" required></label><label>Bezeichnung<input name="label" required></label><label>Abschnitt<input name="section_name" value="Zusatzangaben" placeholder="z. B. Alarmdaten" required></label><label>Typ<select name="field_type"><?php foreach(['text','textarea','number','date','time','datetime','select','multiselect','checkbox','yesno'] as $t):?><option value="<?= e($t) ?>"><?= e($t) ?></option><?php endforeach;?></select></label><label>Optionen<textarea name="options"></textarea></label><label class="check-row"><input type="checkbox" name="required" value="1"><span>Pflicht</span></label><label class="check-row"><input type="checkbox" name="active" value="1" checked><span>Aktiv</span></label><input type="hidden" name="sort_order" value="100"><button class="button primary" type="submit">+ Feld</button></form></div>
